Definition rstrtoll_one_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (endp : word) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 1) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (bv_unsigned endp, bv_unsigned endp + 8)]%Z m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' (bv_unsigned endp) [C8 (Z_to_bv 64 (A_STR_ONE + 1))].

Definition rstrtoll_one_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo : Z) (e0 : word),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  a0 = Z_to_bv 64 A_STR_ONE -> a2 = Z_to_bv 64 0 ->
  bv_unsigned sp mod 16 = 0 ->
  stk asegs m lo (bv_unsigned sp) -> lo + STRTOLL_STACK <= bv_unsigned sp -> 0x67f000 <= lo ->
  bv_unsigned sp <= 0x7fffffffffff ->
  rw_cells asegs m (bv_unsigned a1) [C8 e0] ->
  0x67f000 <= bv_unsigned a1 -> bv_unsigned a1 + 8 <= 0x7fffffffffff ->
  (bv_unsigned a1 + 8 <= lo \/ bv_unsigned sp <= bv_unsigned a1) ->
  rw_cells asegs m AGOT_SSP [C8 (Z_to_bv 64 A_STKCHK_GUARD)] -> acanary m -> mem_inv asegs m ->
  evt asegs (rstrtoll_one_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc a1 lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 ASTRTOLL_REAL) fc None m (seg_rom asegs)).

